import { isFilterSelectValueInOptions } from 'components/Filter/utils/filterSelectDisplayValue';
import type { FilterDataStructure, Option } from 'models/Filters';
import {
  COMMERCIAL_RESULTS_CROSS_FILTER_KEYS,
  COMMERCIAL_RESULTS_PAGE_NAME,
} from 'pages/pillars/ValueCreation/CommercialResults/constants';

const SELECT_A_HINT_LABEL = /^select\s+a\s+/i;

const COMMERCIAL_DISABLED_FILTER_PLACEHOLDERS: Partial<
  Record<(typeof COMMERCIAL_RESULTS_CROSS_FILTER_KEYS)[number], string>
> = {
  non_alcoholic: 'No',
  growth_levers: 'No Levers',
  beer_price_segment: 'No Segments',
  portfolios: 'No Portfolios',
};

function isAllFilterLiteral(value: unknown): boolean {
  if (value == null || value === '') {
    return true;
  }
  if (typeof value === 'string') {
    return value.toUpperCase() === 'ALL';
  }
  return false;
}

function isSelectAHintLabel(label: unknown): boolean {
  return typeof label === 'string' && SELECT_A_HINT_LABEL.test(label);
}

/**
 * Preset row that represents the open / “no narrow filter” state (`All`, null, or
 * BFF hint labels like “Select a Brand”). Not shown as a pickable menu item on CR.
 */
export function isCommercialFilterBaselineOption(option: Option): boolean {
  if (isAllFilterLiteral(option?.value)) {
    return true;
  }
  return isSelectAHintLabel(option?.label);
}

export function isCommercialFilterBaselineValue(value: unknown): boolean {
  return isAllFilterLiteral(value);
}

export function isCommercialResultsFilterPage(pageName: string): boolean {
  return pageName === COMMERCIAL_RESULTS_PAGE_NAME;
}

export function getCommercialDisabledFilterPlaceholder(
  fieldKey: string,
): string | undefined {
  return COMMERCIAL_DISABLED_FILTER_PLACEHOLDERS[
    fieldKey as (typeof COMMERCIAL_RESULTS_CROSS_FILTER_KEYS)[number]
  ];
}

/** Options passed to react-select — baseline rows removed on Commercial Results. */
export function filterCommercialSelectOptions(
  pageName: string,
  options: Option[],
): Option[] {
  if (!isCommercialResultsFilterPage(pageName)) {
    return options;
  }
  return options.filter((option) => !isCommercialFilterBaselineOption(option));
}

/**
 * Closed-state value for drawer selects: `null` when baseline so placeholder shows;
 * otherwise the primitive value if it exists in the selectable list.
 */
export function resolveCommercialDrawerSelectValue(
  pageName: string,
  formValue: unknown,
  defaultFromRegistry: unknown,
  selectableOptions: Option[],
): string | null {
  if (!isCommercialResultsFilterPage(pageName)) {
    return null;
  }

  const effective = formValue ?? defaultFromRegistry;

  if (isCommercialFilterBaselineValue(effective)) {
    return null;
  }

  if (isFilterSelectValueInOptions(selectableOptions, effective)) {
    if (typeof effective === 'string') {
      return effective;
    }
    if (typeof effective === 'number') {
      return String(effective);
    }
  }

  if (typeof effective === 'string') {
    const byLabel = selectableOptions.find(
      (option) => String(option.label) === effective,
    );
    if (byLabel?.value != null && byLabel.value !== '') {
      return String(byLabel.value);
    }
  }

  return null;
}

type FilterDimensionWithEnabled = {
  enabled?: boolean;
};

/** Whether a Commercial Results V2 field should be interactive in the drawer. */
export function isCommercialFilterFieldEnabled(
  pageName: string,
  fieldKey: string,
  dataFilters: FilterDataStructure | undefined,
): boolean {
  if (!isCommercialResultsFilterPage(pageName)) {
    return true;
  }

  if (
    !COMMERCIAL_RESULTS_CROSS_FILTER_KEYS.includes(
      fieldKey as (typeof COMMERCIAL_RESULTS_CROSS_FILTER_KEYS)[number],
    )
  ) {
    return true;
  }

  const dimension = dataFilters?.[fieldKey] as
    | FilterDimensionWithEnabled
    | undefined;

  if (!dimension || typeof dimension !== 'object') {
    return false;
  }

  return dimension.enabled !== false;
}
